    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;

struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let q = query.query;

        // Read-only lookup against the knowledge-base handle granted by `with`.
        let knowledge = kb_read::lookup(&q.question);

        // `requires` bounds question to <= 512, so passing it through keeps
        // `ensures len(question) <= 512`.
        ConversationContext {
            intent: q.intent,
            question: q.question,
            knowledge,
        }
    }
}

export!(Node);
